-- Подсадка — в открытую версию: пункт судит только её (решение владельца 2026-10-07).
WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TPROBE3', м.id, 9997, 'подсадка самотеста', 'S', 'not_started', 'dev', 'declared' FROM (SELECT (SELECT m.id FROM project_plan_milestones m JOIN version_scope s ON s.project_id = m.project_id AND s.version = m.version_id WHERE m.project_id = $1 ORDER BY CASE coalesce(s.scope, 'open') WHEN 'open' THEN 0 WHEN 'closed' THEN 1 ELSE 2 END, m.id LIMIT 1) AS id) м WHERE м.id IS NOT NULL RETURNING id) INSERT INTO task_requirement(project_id, task_id, requirement_id) SELECT $1, t.id, sr.requirement_id FROM t, project_screen_requirements sr WHERE sr.project_id=$1 LIMIT 1
